-- MySQL dump — jurong_marine
-- NOTE from safety officer: severity scale was 1=most severe until 30 Jun 2025; from 1 Jul 2025 we follow new WSH matrix where 5=most severe. Old records NOT converted.
-- Compatible with MySQL 8.x / MySQL Workbench import
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
CREATE DATABASE IF NOT EXISTS `jurong_marine` DEFAULT CHARACTER SET utf8mb4;
USE `jurong_marine`;

DROP TABLE IF EXISTS `machines`;
CREATE TABLE `machines` (
  `machine_id` VARCHAR(10) PRIMARY KEY,
  `machine_name` VARCHAR(40),
  `model` VARCHAR(40),
  `year_installed` INT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `employees`;
CREATE TABLE `employees` (
  `emp_id` INT PRIMARY KEY,
  `emp_code` VARCHAR(8),
  `emp_name` VARCHAR(60),
  `trade` VARCHAR(20),
  `shift` VARCHAR(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `work_orders`;
CREATE TABLE `work_orders` (
  `wo_id` INT PRIMARY KEY,
  `machine_id` VARCHAR(10),
  `wo_type` VARCHAR(12),
  `description` VARCHAR(80),
  `wo_date` DATE,
  `duration_hrs` DECIMAL(5,1),
  `cost_sgd` DECIMAL(8,2),
  `emp_code` VARCHAR(8),
  `status` VARCHAR(16)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `safety_incidents`;
CREATE TABLE `safety_incidents` (
  `incident_id` INT PRIMARY KEY,
  `incident_date` DATE,
  `machine_id` VARCHAR(10),
  `description` VARCHAR(90),
  `severity` INT,
  `lost_days` INT,
  `emp_code` VARCHAR(8),
  `reporting` VARCHAR(30)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;